CREATE TABLE projects(id TEXT PRIMARY KEY, repo_full_name TEXT, repo_id INTEGER, local_checkout TEXT NOT NULL, mode TEXT NOT NULL DEFAULT 'personal' CHECK(mode IN('personal','eos')), visibility TEXT, created_at TEXT NOT NULL);
CREATE TABLE project_settings(project_id TEXT NOT NULL REFERENCES projects(id), version INTEGER NOT NULL, oversight TEXT NOT NULL DEFAULT 'minimal', allowed_providers_json TEXT NOT NULL DEFAULT '[]', never_sent_globs_json TEXT NOT NULL DEFAULT '[]', sprint_day INTEGER, scan_time TEXT, timezone TEXT, retention_json TEXT NOT NULL DEFAULT '{}', effective_at TEXT NOT NULL, set_by TEXT NOT NULL, PRIMARY KEY(project_id,version));
CREATE TABLE allowlist(github_user_id INTEGER PRIMARY KEY, login_at_add TEXT NOT NULL, added_at TEXT NOT NULL, added_by TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS passkeys(id TEXT PRIMARY KEY, credential_json TEXT NOT NULL, created_at INTEGER NOT NULL, last_used_at INTEGER);
CREATE TABLE IF NOT EXISTS passkey_setup(id INTEGER PRIMARY KEY CHECK(id=1), code_hash TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE artifacts(sha256 TEXT PRIMARY KEY CHECK(length(sha256)=64), size INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE work_items(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), kind TEXT NOT NULL DEFAULT 'personal' CHECK(kind IN('personal','eos')), title TEXT NOT NULL, github_issue_number INTEGER, state TEXT NOT NULL DEFAULT 'new', priority TEXT, sprint_id TEXT, approved_plan_revision_id TEXT REFERENCES revisions(id), created_at TEXT NOT NULL, repo_slug TEXT NOT NULL, slug TEXT NOT NULL, session_json TEXT NOT NULL, state_json TEXT NOT NULL DEFAULT '{}', closed_at INTEGER, merged_at INTEGER, outcome TEXT, deleted_at INTEGER, UNIQUE(repo_slug,slug));
CREATE TABLE work_item_deps(item_id TEXT NOT NULL REFERENCES work_items(id), depends_on_id TEXT NOT NULL REFERENCES work_items(id), PRIMARY KEY(item_id,depends_on_id), CHECK(item_id<>depends_on_id));
CREATE TABLE revisions(id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES work_items(id), doc_kind TEXT NOT NULL, number INTEGER NOT NULL, content_sha256 TEXT NOT NULL REFERENCES artifacts(sha256), created_by TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(item_id,doc_kind,number), UNIQUE(item_id,doc_kind,content_sha256));
CREATE TRIGGER revisions_no_update BEFORE UPDATE ON revisions BEGIN SELECT RAISE(ABORT,'revisions are immutable'); END;
CREATE TRIGGER revisions_no_delete BEFORE DELETE ON revisions BEGIN SELECT RAISE(ABORT,'revisions are permanent'); END;
CREATE TABLE plan_tasks(id TEXT PRIMARY KEY, revision_id TEXT NOT NULL REFERENCES revisions(id), task_key TEXT NOT NULL, area TEXT, title TEXT NOT NULL, phase TEXT, review_tag INTEGER NOT NULL DEFAULT 0 CHECK(review_tag IN(0,1)), UNIQUE(revision_id,task_key));
CREATE TABLE task_progress(item_id TEXT NOT NULL REFERENCES work_items(id), task_key TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('pending','done')), updated_by_attempt TEXT, updated_at TEXT NOT NULL, PRIMARY KEY(item_id,task_key));
CREATE TABLE gates(id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES work_items(id), kind TEXT NOT NULL CHECK(kind IN('research','plan','milestone','pr','sprint','production')), target_digest TEXT NOT NULL, target_sha TEXT, policy_version INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL, github_comment_id INTEGER, created_at TEXT NOT NULL, closed_at TEXT);
CREATE TABLE decisions(id TEXT PRIMARY KEY, gate_id TEXT NOT NULL REFERENCES gates(id), source TEXT NOT NULL CHECK(source IN('plantool','github')), actor_github_id INTEGER, actor_passkey_id TEXT REFERENCES passkeys(id), source_event_id TEXT NOT NULL, decision TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(gate_id,source_event_id));
CREATE TABLE attempts(id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES work_items(id), role TEXT NOT NULL, generation INTEGER NOT NULL, model_route TEXT NOT NULL, state TEXT NOT NULL, worktree TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, outcome_json TEXT, idempotency_key TEXT NOT NULL UNIQUE, run_json TEXT NOT NULL, hidden INTEGER NOT NULL DEFAULT 0 CHECK(hidden IN(0,1)));
CREATE TABLE leases(id INTEGER PRIMARY KEY CHECK(id=1), holder_attempt_id TEXT REFERENCES attempts(id), holder_kind TEXT, model_route TEXT, acquired_at TEXT, expires_at TEXT);
CREATE TABLE budgets(route TEXT NOT NULL, window_kind TEXT NOT NULL, window_start TEXT NOT NULL, used_requests INTEGER NOT NULL DEFAULT 0, used_tokens INTEGER NOT NULL DEFAULT 0, exhausted_until TEXT, PRIMARY KEY(route,window_kind,window_start));
CREATE TABLE external_bindings(local_type TEXT NOT NULL, local_id TEXT NOT NULL, provider TEXT NOT NULL, external_id TEXT NOT NULL, url TEXT NOT NULL, UNIQUE(provider,external_id));
CREATE TABLE github_cursors(resource TEXT PRIMARY KEY, etag TEXT, last_seen_at TEXT);
CREATE TABLE outbox(id TEXT PRIMARY KEY, aggregate_id TEXT NOT NULL, kind TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL, delivered_at TEXT, attempts INTEGER NOT NULL DEFAULT 0, idempotency_key TEXT UNIQUE, result_json TEXT);
CREATE TABLE inbox(source TEXT NOT NULL, external_event_id TEXT NOT NULL, processed_at TEXT NOT NULL, result TEXT NOT NULL, PRIMARY KEY(source,external_event_id));
CREATE TABLE channels(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL);
CREATE TABLE threads(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), item_id TEXT REFERENCES work_items(id), channel_id TEXT REFERENCES channels(id), title TEXT NOT NULL);
CREATE TABLE messages(id TEXT PRIMARY KEY, thread_id TEXT NOT NULL REFERENCES threads(id), sender_role TEXT NOT NULL, body TEXT NOT NULL, mentions_json TEXT NOT NULL DEFAULT '[]', artifact_refs_json TEXT NOT NULL DEFAULT '[]', dedupe_key TEXT UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE sprints(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), week TEXT NOT NULL, tracking_issue_number INTEGER, state TEXT NOT NULL, snapshot_comment_id INTEGER);
CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT, at TEXT NOT NULL, actor_kind TEXT NOT NULL, actor_id TEXT, action TEXT NOT NULL, subject TEXT NOT NULL, digest TEXT, metadata_json TEXT NOT NULL);
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'audit is append-only'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'audit is append-only'); END;
CREATE TABLE runs_summary(attempt_id TEXT PRIMARY KEY REFERENCES attempts(id), provider TEXT NOT NULL, model TEXT, requests INTEGER NOT NULL DEFAULT 0, tokens_in INTEGER NOT NULL DEFAULT 0, tokens_out INTEGER NOT NULL DEFAULT 0, duration_ms INTEGER NOT NULL DEFAULT 0, pinned INTEGER NOT NULL DEFAULT 0 CHECK(pinned IN(0,1)));
CREATE TABLE artifact_refs(owner_type TEXT NOT NULL, owner_id TEXT NOT NULL, kind TEXT NOT NULL, sha256 TEXT NOT NULL REFERENCES artifacts(sha256), created_at INTEGER NOT NULL, PRIMARY KEY(owner_type,owner_id,kind));
CREATE TABLE settings(key TEXT PRIMARY KEY,value_json TEXT NOT NULL);
CREATE INDEX revisions_item ON revisions(item_id,doc_kind,number);
CREATE INDEX attempts_item ON attempts(item_id,started_at);
CREATE INDEX refs_sha ON artifact_refs(sha256);
CREATE INDEX outbox_pending ON outbox(delivered_at);
CREATE TABLE run_events(id INTEGER PRIMARY KEY AUTOINCREMENT, attempt_id TEXT NOT NULL REFERENCES attempts(id), seq INTEGER NOT NULL, content_sha256 TEXT NOT NULL REFERENCES artifacts(sha256), UNIQUE(attempt_id,seq));
